"use client"

import { type ReactNode } from "react"
import { motion, useReducedMotion, type Variants } from "motion/react"

// Direction-aware hover easing: clean ease-in on the way up, a restrained
// settle on the return — a barely-there overshoot for a premium feel.
const DUR = 0.42
const EASE_IN = [0.22, 1, 0.36, 1] as const
const EASE_OUT = [0.34, 1.2, 0.64, 1] as const // slight overshoot, no big bounce

const cardMotion: Variants = {
    rest: { y: 0, transition: { duration: DUR, ease: EASE_OUT } },
    hover: { y: -4, transition: { duration: DUR, ease: EASE_IN } },
}
const tileMotion: Variants = {
    rest: { x: 0, y: 0, transition: { duration: DUR, ease: EASE_OUT } },
    hover: { x: -3, y: -4, transition: { duration: DUR, ease: EASE_IN } },
}

// Faithful to src-bento-2.tsx: a centered header + a 2-up top row and a 3-up
// bottom row of cards. Each card has an 80x80 icon tile (top-left), a title,
// and a short description. Holographic sweep on tile hover follows the D2 brand.

// Conversational-AI glyph — from public/Message Icon 1.svg. Metallic linear
// gradient fill (#FFF -> #101010) plus an inner shadow, kept inline so the
// filter and gradients render exactly as designed.
