// Privacy glyph — from Locked Padlock 1.svg.
function PadlockIcon({ className }: { className?: string }) {
    return (
        <svg viewBox="0 0 40 40" fill="none" xmlns="http://www.w3.org/2000/svg" className={className}>
            <g clipPath="url(#pad_clip)">
                <path d="M25.7865 13.2782C27.0688 13.8205 28.2546 14.5329 29.3302 15.4016V9.26117C29.3302 4.15489 25.1753 0 20.069 0H19.9265C14.8248 0 10.6699 4.15489 10.6699 9.26117V15.4016C11.7454 14.533 12.9312 13.8206 14.2135 13.2782C14.5582 13.1311 14.9121 12.9978 15.266 12.8783V9.26117C15.266 6.68735 17.3573 4.59612 19.9311 4.59612H20.0736C22.6474 4.59612 24.7386 6.68735 24.7386 9.26117V12.8829C25.0879 12.9978 25.4418 13.1311 25.7865 13.2782Z" fill="url(#pad_p0)" />
                <path d="M6.97461 26.9746C6.97461 34.1675 12.8071 39.9999 20 39.9999C27.1929 39.9999 33.0254 34.172 33.0254 26.9746C33.0254 23.4402 31.6144 20.2321 29.3302 17.8834C28.0433 16.5644 26.4806 15.5164 24.734 14.8316C23.2679 14.2571 21.6684 13.9446 20 13.9446C18.3317 13.9446 16.7322 14.2571 15.266 14.8316C13.5195 15.5119 11.9568 16.5598 10.6699 17.8834C8.38102 20.2321 6.97461 23.4402 6.97461 26.9746ZM16.6448 24.3456C16.6908 22.5669 18.1385 21.1191 19.9172 21.0777C21.8062 21.0317 23.3551 22.5531 23.3551 24.4329C23.3551 24.6306 23.3367 24.8235 23.3046 25.0074C23.139 25.9588 22.5738 26.7769 21.7832 27.2733C21.4568 27.4801 21.2914 27.8662 21.3742 28.2385L22.3716 32.9679C22.4314 33.2529 22.2153 33.5241 21.9211 33.5241H18.0788C17.7847 33.5241 17.5686 33.2575 17.6284 32.9679L18.6257 28.2385C18.7039 27.8616 18.543 27.4755 18.2167 27.2687C17.4262 26.7723 16.8609 25.9588 16.6953 25.0028C16.6586 24.7914 16.6402 24.5708 16.6448 24.3456Z" fill="url(#pad_p1)" />
            </g>
            <defs>
                <linearGradient id="pad_p0" x1="20" y1="0" x2="20" y2="11.4549" gradientUnits="userSpaceOnUse"><stop stopColor="white" /><stop offset="1" stopColor="#101010" /></linearGradient>
                <linearGradient id="pad_p1" x1="20" y1="13.9446" x2="20" y2="33.3233" gradientUnits="userSpaceOnUse"><stop stopColor="white" /><stop offset="1" stopColor="#101010" /></linearGradient>
